<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($pageTitle) ?> | Lokal Culture</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/orders.css"></head><body class="dashboard-page"><header class="site-header"><a class="brand" href="/">✦ LOKAL <em>CULTURE</em></a><nav class="header-actions"><a href="/account">Dashboard</a><a href="/logout">Sign out</a></nav></header><main class="orders-shell"><p class="eyebrow"><?= htmlspecialchars($eyebrow) ?></p><h1><?= htmlspecialchars($heading) ?></h1><div class="orders-table"><div class="order-row order-header"><span>Order</span><span>Customer</span><span>Status</span><span>Total</span><span>Date</span></div><?php foreach ($orders as $order): ?><a class="order-row" href="/orders/<?= urlencode($order['order_number']) ?>"><strong><?= htmlspecialchars($order['order_number']) ?></strong><span><?= htmlspecialchars($order['customer'] ?? 'Your order') ?></span><i class="status-<?= htmlspecialchars($order['status']) ?>"><?= htmlspecialchars(ucfirst($order['status'])) ?></i><strong>₹<?= number_format((float) $order['grand_total'], 0) ?></strong><span><?= htmlspecialchars(date('d M Y', strtotime($order['created_at']))) ?></span></a><?php endforeach; ?></div><?php if (!$orders): ?><p class="empty-state">No orders yet.</p><?php endif; ?></main></body></html>